iption"] = "Implement the next unfinished task from PLAN.md — locate the current phase, read the linked DESIGN.md section if present, implement, and tick the checkbox. Use for executing lite workflow work without proposal or validation ceremony." }, { ["id"] = "flowkit:plan", ["kit"] = "flowkit", ["category"] = "lite", ["tags"] = { "plan", "lite" }, ["path"] = "flowkit/skills/plan", ["description"] = "Lite workflow planner — breaks SPEC.md into a phased PLAN.md with task checkboxes, dependency ordering, and per-task acceptance criteria. Use in the lite workflow after refine, before building." }, { ["id"] = "flowkit:refine", ["kit"] = "flowkit", ["category"] = "lite", ["tags"] = { "spec", "lite" }, ["path"] = "flowkit/skills/refine", ["description"] = "Refine a vague idea into a concrete SPEC.md using structured questioning modes (Sherlock/Poirot/Columbo). The lite workflow clarify convergence tool — use after brainstorm, before plan." }, { ["id"] = "flowkit:pickup", ["kit"] = "flowkit", ["category"] = "lite", ["tags"] = { "pickup", "shared" }, ["path"] = "flowkit/skills/pickup", ["description"] = "Check sdd workflow progress and pick up work for a new session or agent. Shared by the lite and default workflows — reads the workflow block in AGENTS.md, then SPEC.md/PLAN.md/DESIGN.md/HANDOFF.md, and reports where we are and what's next. Use when starting a new session, after an interruption, or when asked \"where are we / what's next\"." }, { ["id"] = "flowkit:rest", ["kit"] = "flowkit", ["category"] = "lite", ["tags"] = { "rest", "shared" }, ["path"] = "flowkit/skills/rest", ["description"] = "Pause in-progress work without archiving — survey per the AGENTS.md workflow block, record a parked note in PLAN.md, append HANDOFF.md, report status. Shared by the lite and default workflows. Use on pause, handoff, or session end with in-progress work." }, { ["id"] = "flowkit:upgrade", ["kit"] = "flowkit", ["category"] = "lite", ["tags"] = { "upgrade", "shared" }, ["path"] = "flowkit/skills/upgrade", ["description"] = "Upgrade a lite workflow project to the default (lightspec) workflow — keep SPEC.md (Goal/What/Decisions), DESIGN.md, and HANDOFF.md; add the lightspec/ layer; migrate PLAN.md tasks into the first change's tasks.md; swap the AGENTS.md workflow block. Use when a lite project outgrows the file-driven flow." }, { ["id"] = "forgekit:app-sdd", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "lightspec" }, ["path"] = "forgekit/skills/app-sdd", ["description"] = "Default workflow guide (lightspec-based). Use when starting a session or task in a lightspec project — routes to the right command, skill, or agent across the workflow (init → clarify → plan → code → review → archive). The four files (SPEC/PLAN/DESIGN/HANDOFF) hold the simple project-level view; per-change detail lives in lightspec/." }, { ["id"] = "forgekit:building", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "build" }, ["path"] = "forgekit/skills/building", ["description"] = "Implements code in thin vertical slices with quality checks, ponytail minimal code philosophy, and quick-fix/incremental/tdd/plan-driven modes — including plan execution, mismatch handling, and acceptance validation." }, { ["id"] = "forgekit:init-sdd", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "init", "lightspec" }, ["path"] = "forgekit/skills/init-sdd", ["description"] = "Initialize a project with the default (lightspec) workflow — creates `lightspec/` (copied workflow doc), writes `SPEC.md` and `PLAN.md`, updates `AGENTS.md` and `README.md`. The four files (SPEC/PLAN/DESIGN/HANDOFF) stay simple; detail lives in `lightspec/`. Use for a new project that needs proposal/archive discipline." }, { ["id"] = "forgekit:knowledge-capture", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "archive" }, ["path"] = "forgekit/skills/knowledge-capture", ["description"] = "Compound skill for capturing decisions, solutions, and lessons learned — stores to docs/solutions/ with dedup" }, { ["id"] = "forgekit:planning", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "plan", "lightspec" }, ["path"] = "forgekit/skills/planning", ["description"] = "Creates specs and breaks down work into tasks using lightspec, with quick-plan/spec/architecture modes — including vertical-slice decomposition for complex features." }, { ["id"] = "forgekit:planning-and-task-breakdown", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "plan", "lightspec" }, ["path"] = "forgekit/skills/planning-and-task-breakdown", ["description"] = "Breaks work into ordered tasks. Use when you have a spec or clear requirements and need to break work into implementable tasks. Use when a task feels too large to start, when you need to estimate scope, or when parallel work is possible." }, { ["id"] = "forgekit:reviewing", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "review" }, ["path"] = "forgekit/skills/reviewing", ["description"] = "Reviews code across five axes (correctness, readability, architecture, security, performance) with ponytail over-engineering check — plus fresh-perspective (blind-spot) and criteria-walk (acceptance verification) review modes." }, { ["id"] = "forgekit:shipping", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "ship" }, ["path"] = "forgekit/skills/shipping", ["description"] = "Prepares code for release with git workflow, documentation, and commit/release/audit modes." }, { ["id"] = "forgekit:spec-driven-development", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "spec", "lightspec", "clarify" }, ["path"] = "forgekit/skills/spec-driven-development", ["description"] = "Clarifies requirements and produces a concrete spec — SPEC.md (lite workflow) or a lightspec proposal (lightspec workflow). The sdd clarify stage's specification engine — use when requirements are unclear, ambiguous, or exist only as a vague idea, before planning begins." }, { ["id"] = "forgekit:spec-proposal", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "spec", "lightspec" }, ["path"] = "forgekit/skills/spec-proposal", ["description"] = "Scaffolds a new sdd change proposal — clarifies requirements, writes proposal/design/tasks/spec deltas, reviews with plan-reviewer, validates. The lightspec workflow's clarify-to-proposal entry — use for new features, changes, or any non-trivial work before implementation." }, { ["id"] = "forgekit:spec-router", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "spec", "lightspec" }, ["path"] = "forgekit/skills/spec-router", ["description"] = "Entry point for spec-driven development — interviews users, creates and validates specs using lightspec." }, { ["id"] = "forgekit:test-router", ["kit"] = "forgekit", ["category"] = "spec", ["tags"] = { "test" }, ["path"] = "forgekit/skills/test-router", ["description"] = "Detects project type, runs appropriate tests, validates against spec scenarios, and reports results." }, { ["id"] = "devkit:advisor", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "review", "advice" }, ["path"] = "devkit/skills/advisor", ["description"] = "Second-opinion advisor — dispatches 1-2 subagents (advice + hard devil's-advocate) to review a decision, design, plan, or code before you commit to it" }, { ["id"] = "devkit:api-and-interface-design", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "design", "api" }, ["path"] = "devkit/skills/api-and-interface-design", ["description"] = "Guides stable API and interface design. Use when designing APIs, module boundaries, or any public interface. Use when creating REST or GraphQL endpoints, defining type contracts between modules, or establishing boundaries between frontend and backend." }, { ["id"] = "devkit:aur-guides", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "packaging", "aur" }, ["path"] = "devkit/skills/aur-guides", ["description"] = "Master skill for AUR (Arch User Repository) package development. Dispatches to specialized sub-skills for creating PKGBUILDs, auditing packages, submitting to AUR, and more. Use when working with AUR packages, PKGBUILDs, makepkg, pacman, or any Arch Linux packaging task." }, { ["id"] = "devkit:browser-testing-with-devtools", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "test", "frontend" }, ["path"] = "devkit/skills/browser-testing-with-devtools", ["description"] = "Tests in real browsers. Use when building or debugging anything that runs in a browser. Use when you need to inspect the DOM, capture console errors, analyze network requests, profile performance, or verify visual output with real runtime data via Chrome DevTools MCP." }, { ["id"] = "devkit:ci-cd-and-automation", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "ci-cd", "build" }, ["path"] = "devkit/skills/ci-cd-and-automation", ["description"] = "Automates CI/CD pipeline setup. Use when setting up or modifying build and deployment pipelines. Use when you need to automate quality gates, configure test runners in CI, or establish deployment strategies." }, { ["id"] = "devkit:code-review-and-quality", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "review", "quality" }, ["path"] = "devkit/skills/code-review-and-quality", ["description"] = "Conducts multi-axis code review. Use before merging any change. Use when reviewing code written by yourself, another agent, or a human. Use when you need to assess code quality across multiple dimensions before it enters the main branch — includes PR triage, parallel lens dispatch, and layered architecture review for large changes." }, { ["id"] = "devkit:code-simplification", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "simplify" }, ["path"] = "devkit/skills/code-simplification", ["description"] = "Simplifies code for clarity. Use when refactoring code for clarity without changing behavior. Use when code works but is harder to read, maintain, or extend than it should be. Use when reviewing code that has accumulated unnecessary complexity." }, { ["id"] = "devkit:context-engineering", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "context", "documentation" }, ["path"] = "devkit/skills/context-engineering", ["description"] = "Optimizes agent context setup. Use when starting a new session, when agent output quality degrades, when switching between tasks, or when you need to configure rules files and context for a project." }, { ["id"] = "devkit:context7", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "documentation", "research" }, ["path"] = "devkit/skills/context7", ["description"] = "Retrieve up-to-date documentation for software libraries, frameworks, and components via the Context7 API. This skill should be used when looking up documentation for any programming library or framework, finding code examples for specific APIs or features, verifying correct usage of library functions, or obtaining current information about library APIs that may have changed since training." }, { ["id"] = "devkit:craft-skill", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "design", "skill" }, ["path"] = "devkit/skills/craft-skill", ["description"] = ">" }, { ["id"] = "devkit:debugging-and-error-recovery", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "debug" }, ["path"] = "devkit/skills/debugging-and-error-recovery", ["description"] = "Guides systematic root-cause debugging. Use when tests fail, builds break, behavior doesn't match expectations, or you encounter any unexpected error. Use when you need a systematic approach to finding and fixing the root cause rather than guessing." }, { ["id"] = "devkit:deprecation-and-migration", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "migration", "maintain" }, ["path"] = "devkit/skills/deprecation-and-migration", ["description"] = "Manages deprecation and migration. Use when removing old systems, APIs, or features. Use when migrating users from one implementation to another. Use when deciding whether to maintain or sunset existing code." }, { ["id"] = "devkit:designing-agents", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "design", "agent" }, ["path"] = "devkit/skills/designing-agents", ["description"] = "Designs and writes a focused artifact another agent runs — an agent persona in agents/ or a workflow skill in skills/. Use when authoring a reviewer or specialist persona, a repeatable process skill — or when rewriting one that is under-specified, overlapping, or being ignored." }, { ["id"] = "devkit:discovery", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "research", "clarify" }, ["path"] = "devkit/skills/discovery", ["description"] = "Understands user demands through structured exploration — explore/brainstorm/deep-dive modes — before planning begins." }, { ["id"] = "devkit:documentation-and-adrs", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "documentation" }, ["path"] = "devkit/skills/documentation-and-adrs", ["description"] = "Records decisions and documentation. Use when making architectural decisions, changing public APIs, shipping features, or when you need to record context that future engineers and agents will need to understand the codebase." }, { ["id"] = "devkit:expert-panel", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "review", "analysis" }, ["path"] = "devkit/skills/expert-panel", ["description"] = "Multi-perspective analysis — parallel analysis from different role perspectives to evaluate decisions, designs, and plans" }, { ["id"] = "devkit:frontend-ui-engineering", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "frontend", "design" }, ["path"] = "devkit/skills/frontend-ui-engineering", ["description"] = "Builds production-quality UIs. Use when building or modifying user-facing interfaces. Use when creating components, implementing layouts, managing state, or when the output needs to look and feel production-quality rather than AI-generated." }, { ["id"] = "devkit:git-workflow-and-versioning", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "git" }, ["path"] = "devkit/skills/git-workflow-and-versioning", ["description"] = "Structures git workflow practices. Use when making any code change. Use when committing, branching, resolving conflicts, or when you need to organize work across multiple parallel streams." }, { ["id"] = "devkit:grill-me", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "spec", "interview" }, ["path"] = "devkit/skills/grill-me", ["description"] = "Grill the user relentlessly about a plan, decision, or idea. Use when the user wants to stress-test their thinking, or uses any 'grill' trigger phrases." }, { ["id"] = "devkit:idea-refine", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "spec", "clarify" }, ["path"] = "devkit/skills/idea-refine", ["description"] = "Refines ideas iteratively. Refine ideas through structured divergent and convergent thinking. Use \"idea-refine\" or \"ideate\" to trigger." }, { ["id"] = "devkit:interview-me", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "spec", "interview" }, ["path"] = "devkit/skills/interview-me", ["description"] = "Extracts what the user actually wants instead of what they think they should want. Achieves this through one-question-at-a-time interview until ~95% confidence about the underlying intent. Use when an ask is underspecified (\"build me X\" without \"for whom\" or \"why now\"), when the user explicitly invokes (\"interview me\", \"grill me\", \"are we sure?\", \"stress-test my thinking\"), or when you catch yourself silently filling in ambiguous requirements before any plan, spec, or code exists." }, { ["id"] = "devkit:orchestrate", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "orchestrate" }, ["path"] = "devkit/skills/orchestrate", ["description"] = "Multi-agent orchestration — dispatch specialists in parallel, own acceptance assertions, synthesize results" }, { ["id"] = "devkit:peer-review", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "review" }, ["path"] = "devkit/skills/peer-review", ["description"] = "External-perspective review of a change set before ship by a fresh agent who" }, { ["id"] = "devkit:performance-optimization", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "performance" }, ["path"] = "devkit/skills/performance-optimization", ["description"] = "Optimizes application performance. Use when performance requirements exist, when you suspect performance regressions, or when Core Web Vitals or load times need improvement. Use when profiling reveals bottlenecks that need fixing." }, { ["id"] = "devkit:ponytail", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "simplify", "ponytail" }, ["path"] = "devkit/skills/ponytail", ["description"] = "Minimal code philosophy — the 7-rung ladder, intensity levels, and comment convention for avoiding over-engineering" }, { ["id"] = "devkit:ponytail-audit", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "review", "simplify", "ponytail" }, ["path"] = "devkit/skills/ponytail-audit", ["description"] = "Audit entire repository for over-engineering opportunities, ranked by cut potential" }, { ["id"] = "devkit:ponytail-debt", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "simplify", "ponytail" }, ["path"] = "devkit/skills/ponytail-debt", ["description"] = "Harvest ponytail comments into a debt ledger — track intentional simplifications" }, { ["id"] = "devkit:ponytail-gain", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "simplify", "ponytail" }, ["path"] = "devkit/skills/ponytail-gain", ["description"] = "Display ponytail benchmark scoreboard — LOC, cost, and speed improvements from published data" }, { ["id"] = "devkit:ponytail-help", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "simplify", "ponytail" }, ["path"] = "devkit/skills/ponytail-help", ["description"] = "Quick reference card for ponytail — levels, commands, and the 7-rung ladder" }, { ["id"] = "devkit:ponytail-review", ["kit"] = "devkit", ["category"] = "dev", ["tags"] = { "review"